const inputItems = $input.all();
const companiesSet = new Set();
const domainsSet = new Set();
const accounts = [];

for (const item of inputItems) {
  const r = item.json || {};
  const activeFlag = String(r.active ?? 'true').trim().toLowerCase();
  if (activeFlag === 'false' || activeFlag === '0' || activeFlag === 'no') continue;

  const accountName = String(r.accountName || r.company || '').trim();
  const rawDomain = String(r.domain || '').trim().toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split(/[/?#]/)[0];
  const atsTarget = String(r.atsTarget || accountName).trim();
  if (!accountName && !rawDomain) continue;

  const canonicalName = accountName || rawDomain;
  if (atsTarget) companiesSet.add(atsTarget);
  if (rawDomain && rawDomain.includes('.')) domainsSet.add(rawDomain);

  accounts.push({
    accountName: canonicalName,
    domain: rawDomain || '',
    atsTarget: atsTarget || canonicalName,
    owner: String(r.owner || 'Unassigned').trim(),
  });
}

const companies = Array.from(companiesSet).slice(0, 50);
const targets = Array.from(domainsSet).slice(0, 30);

return [
  {
    json: {
      hasCompanies: companies.length > 0,
      hasDomains: targets.length > 0,
      accountCount: accounts.length,
      accounts,
      companies,
      targets,
      scanDate: new Date().toISOString().slice(0, 10),
    },
  },
];

const valid = $input.all()
  .filter(i => i.json && (i.json.jobId || i.json.title))
  .map(i => ({ json: { ...i.json, _signalType: 'hiring' } }));
return valid.length > 0 ? valid : [{ json: { _signalType: 'empty' } }];

const valid = $input.all()
  .filter(i => i.json && (i.json.creativeId || i.json.advertiserId))
  .map(i => ({ json: { ...i.json, _signalType: 'ads' } }));
return valid.length > 0 ? valid : [{ json: { _signalType: 'empty' } }];

const HIGH_SENIORITIES = new Set(['senior', 'staff', 'lead', 'manager', 'director', 'executive']);
const STRATEGIC_STACK = new Set(['Kubernetes', 'Snowflake', 'Databricks', 'PyTorch', 'LLM', 'Terraform', 'Salesforce', 'HubSpot']);

const escSlack = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let accountsMeta = [];
let scanDate = new Date().toISOString().slice(0, 10);
try {
  const batch = $('Filter & Build Batch Payloads').first()?.json;
  if (Array.isArray(batch?.accounts)) accountsMeta = batch.accounts;
  if (batch?.scanDate) scanDate = batch.scanDate;
} catch {
  // Standalone test fallback
}

const normKey = (s) => String(s || '')
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/^[a-z]+:/, '')
  .replace(/\.(?:co|com|org|net)\.[a-z]{2}$|\.[a-z]{2,}$/i, '')
  .replace(/\b(inc|ltd|llc|sas|sa|gmbh|ag|corp|corporation|plc)\b/g, '')
  .replace(/[^a-z0-9]/g, '');

// Index every configured account by all its aliases (accountName, domain root, full domain without dots, atsTarget slug)
const metaByAlias = new Map();
for (const acc of accountsMeta) {
  const canonicalKey = normKey(acc.accountName || acc.domain);
  if (!canonicalKey) continue;
  const entry = { ...acc, canonicalKey };
  const aliases = [
    normKey(acc.accountName),
    normKey(acc.domain),
    String(acc.domain || '').toLowerCase().replace(/[^a-z0-9]/g, ''),
    normKey(acc.atsTarget),
  ].filter(Boolean);
  for (const a of aliases) metaByAlias.set(a, entry);
}

const grouped = new Map();
const getBucket = (candidates, fallbackName, fallbackDomain) => {
  let matchedMeta = null;
  for (const c of candidates) {
    if (!c) continue;
    const rawNoPunct = String(c).toLowerCase().replace(/[^a-z0-9]/g, '');
    matchedMeta = metaByAlias.get(normKey(c)) || metaByAlias.get(rawNoPunct) || null;
    if (matchedMeta) break;
  }
  const key = matchedMeta?.canonicalKey || normKey(fallbackDomain || fallbackName);
  if (!key) return null;
  if (!grouped.has(key)) {
    grouped.set(key, {
      accountKey: key,
      accountName: matchedMeta?.accountName || fallbackName || fallbackDomain,
      domain: matchedMeta?.domain || fallbackDomain || '',
      owner: matchedMeta?.owner || 'Unassigned',
      jobs: [],
      ads: [],
    });
  }
  return grouped.get(key);
};

for (const item of $input.all()) {
  const d = item.json || {};
  if (d._signalType === 'hiring') {
    const b = getBucket([d.company, d.companySlug], d.company || d.companySlug, '');
    if (b) b.jobs.push(d);
  } else if (d._signalType === 'ads') {
    const b = getBucket([d.domain, d.target, d.advertiserName], d.advertiserName || d.target, d.domain || d.target);
    if (b) b.ads.push(d);
  }
}

const scored = [];
for (const b of grouped.values()) {
  const newJobsCount = b.jobs.length;
  const newAdsCount = b.ads.length;
  const seniorRoles = b.jobs.filter(j => HIGH_SENIORITIES.has(String(j.seniority || '').toLowerCase()));
  const highSalaryRoles = b.jobs.filter(j => Number(j.salaryAnnualUsdMax || j.salaryAnnualUsdMin || 0) >= 150000);
  const techSet = new Set();
  for (const j of b.jobs) {
    if (Array.isArray(j.techStack)) j.techStack.forEach(t => techSet.add(t));
  }
  const strategicTech = Array.from(techSet).filter(t => STRATEGIC_STACK.has(t));
  const adFormats = Array.from(new Set(b.ads.map(a => a.format).filter(Boolean)));
  const evergreenAds = b.ads.filter(a => Number(a.activeDays || 0) >= 30);

  let intentScore = 0;
  intentScore += Math.min(40, newJobsCount * 10);
  if (seniorRoles.length > 0) intentScore += 15;
  if (highSalaryRoles.length > 0 || strategicTech.length > 0) intentScore += 10;
  intentScore += Math.min(25, newAdsCount * 10);
  if (adFormats.length >= 2 || evergreenAds.length > 0) intentScore += 10;
  intentScore = Math.min(100, intentScore);

  const intentTier = intentScore >= 50 ? 'HOT' : intentScore >= 20 ? 'WARM' : 'QUIET';
  if (intentTier === 'QUIET') continue;

  const angleParts = [];
  if (newJobsCount > 0) {
    angleParts.push(`Hiring ${newJobsCount} new role(s) (${seniorRoles.length} senior/leadership)`);
  }
  if (strategicTech.length > 0) {
    angleParts.push(`Active stack: ${strategicTech.slice(0, 5).join(', ')}`);
  }
  if (newAdsCount > 0) {
    angleParts.push(`${newAdsCount} new Google Ad(s) (${adFormats.join('/') || 'mixed'})`);
  }

  const topJobLinks = b.jobs.slice(0, 3).map(j => `${j.title}${j.salaryRaw ? ` (${j.salaryRaw})` : ''} -> ${j.applyUrl}`).join('\n');
  const topAdLinks = b.ads.slice(0, 3).map(a => `[${a.format}] ${a.firstShownDate || 'new'} (${a.activeDays || 1}d) -> ${a.adUrl}`).join('\n');
  const detectedTechStack = Array.from(techSet).slice(0, 12).join(', ');
  const outreachAngle = angleParts.join(' • ');

  const slackLines = [
    `:fire: *HOT Buying Signal — ${escSlack(b.accountName)}* (Score ${intentScore}/100 | Owner: ${escSlack(b.owner)})`,
    `• *Summary:* ${escSlack(outreachAngle)}`,
  ];
  if (detectedTechStack) slackLines.push(`• *Tech Stack:* ${escSlack(detectedTechStack)}`);
  if (topJobLinks) slackLines.push(`*Top Open Roles:*\n${escSlack(topJobLinks)}`);
  if (topAdLinks) slackLines.push(`*New Google Ads:*\n${escSlack(topAdLinks)}`);
  const slackMessage = slackLines.join('\n').slice(0, 2800);

  scored.push({
    json: {
      signalKey: `${scanDate}:${b.accountKey}`,
      scanDate,
      accountName: b.accountName,
      domain: b.domain,
      owner: b.owner,
      intentScore,
      intentTier,
      newJobsCount,
      seniorRolesCount: seniorRoles.length,
      highSalaryRolesCount: highSalaryRoles.length,
      detectedTechStack,
      newAdsCount,
      adFormats: adFormats.join(', '),
      outreachAngle,
      topJobLinks,
      topAdLinks,
      slackMessage,
    },
  });
}

scored.sort((a, b) => b.json.intentScore - a.json.intentScore);
return scored;
